
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_x_ktbm_4_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_x_ktbm_4", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.778727767344810e+00, -4.681967844866531e+00, -4.546295483285172e+00, -4.358160548875647e+00, -4.101361319810739e+00, -3.758548123642920e+00, -3.314804685347845e+00, -2.763814164892314e+00, -2.116822443889908e+00, -1.426701428557684e+00, -8.525788996498189e-01, -6.237593275077636e-01, -6.160652259500410e-01, -5.127354696262667e-01, -3.454832286884292e-01, -1.904792572021401e-01, -8.533421746432816e-02, -2.860205746500172e-02, -6.168569621730942e-03, -6.956361488051941e-04]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


